                    color=(c.font.color.type, c.font.color.rgb, c.font.color.indexed)
                cells.append(f'{c.coordinate}:v={c.value!r},style={c.style_id},num={c.number_format!r},font={color},fill={c.fill.fgColor.rgb!r}')
        if cells: print(' || '.join(cells[:16]))
PY", "security_risk": "LOW", "summary": "Inspect key template styles and formulas"}

